package jp.tapmarker;
import java.util.*;
public class StateMigrationTest {
 static int n;static void check(boolean b,String s){if(!b)throw new AssertionError(s);n++;System.out.println("PASS "+s);}
 static PhaseEngine.Phase state(String id){PhaseEngine.Phase p=new PhaseEngine.Phase();p.id=id;p.name=id;return p;}
 static PhaseEngine.Watch rule(String id,String history,String next){PhaseEngine.Watch w=new PhaseEngine.Watch();w.id=id;w.name=id;w.regionId="A";w.condition=PhaseEngine.MATCH;w.reference=new float[]{1};w.historyRule=history;w.nextPhase=next;return w;}
 public static void main(String[] args){PhaseEngine e=new PhaseEngine();PhaseEngine.Region r=new PhaseEngine.Region();r.id="A";r.bounds=new float[]{0,0,1,1};e.regions.put(r.id,r);PhaseEngine.Phase reward=state("reward"),upgrade=state("upgrade"),hub=state("hub"),endR=state("endR"),endU=state("endU");endR.terminal=endU.terminal=true;reward.watches.add(rule("pressR","","hub"));upgrade.watches.add(rule("pressU","","hub"));PhaseEngine.Watch br=rule("branchR","pressR","endR"),bu=rule("branchU","pressU","endU");br.historyPhase="reward";bu.historyPhase="upgrade";hub.watches.add(br);hub.watches.add(bu);for(PhaseEngine.Phase p:Arrays.asList(reward,upgrade,hub,endR,endU))e.phases.put(p.id,p);e.initial=e.current="reward";PhaseEngine out=StateMigration.convert(e);check(out!=e,"history model expanded into explicit states");check(out.initial.equals("reward"),"configured start preserved");check(e.phases.get("hub").watches.get(0).historyRule.equals("pressR"),"original backup model unmodified");check(out.phases.size()>e.phases.size(),"common display split into context states");for(PhaseEngine.Phase p:out.phases.values())for(PhaseEngine.Watch w:p.watches)check(w.historyRule.isEmpty()&&w.historyPhase.isEmpty(),"converted transition has no history guards");Map<String,float[]> samples=new HashMap<>();samples.put("A",new float[]{1});out.enter("reward",0);out.observe(samples,1);PhaseEngine.Watch first=out.poll();check(first!=null,"reward entry action available");out.finish(first,2);String rewardHub=out.current;out.observe(samples,3);PhaseEngine.Watch branch=out.poll();check(branch!=null&&branch.name.equals("branchR"),"same image branches to reward using state only");out.finish(branch,4);check(out.terminal(),"reward branch reaches final state");out.enter("upgrade",5);out.observe(samples,6);out.finish(out.poll(),7);check(!out.current.equals(rewardHub),"upgrade and reward histories now distinct nodes");out.observe(samples,8);branch=out.poll();check(branch!=null&&branch.name.equals("branchU"),"same image branches to upgrade using state only");check(out.validate().isEmpty(),"converted automaton validates");PhaseEngine plain=new PhaseEngine();check(StateMigration.convert(plain)==plain,"history-free settings remain unchanged");System.out.println("TOTAL "+n+" migration checks passed; device UI not tested.");}
}
